typedef struct {
    double x, y;
} Point;

static double dist(Point a, Point b) {
    double dx = a.x - b.x;
    double dy = a.y - b.y;
    return sqrt(dx * dx + dy * dy);
}

int main(void) {
    int T;
    if (scanf("%d", &T) != 1) return 0;

    while (T--) {
        Point A, B, C;
        scanf("%lf %lf %lf %lf %lf %lf",
              &A.x, &A.y, &B.x, &B.y, &C.x, &C.y);

        /* Standard notation:
           a = |BC|, b = |CA|, c = |AB|
           s = semiperimeter
           Delta = area
           r = inradius

           Malfatti radii:
           r1 = r * (s - r + d - e - f) / (2 * (s - a))
           r2 = r * (s - r - d + e - f) / (2 * (s - b))
           r3 = r * (s - r - d - e + f) / (2 * (s - c))

           where
           d = sqrt(r^2 + (s-a)^2)
           e = sqrt(r^2 + (s-b)^2)
           f = sqrt(r^2 + (s-c)^2)

           r1, r2, r3 are the circles near vertices A, B, C respectively.
        */

        double a = dist(B, C);
        double b = dist(C, A);
        double c = dist(A, B);

        double s = (a + b + c) / 2.0;

        double area2 = s * (s - a) * (s - b) * (s - c);
        if (area2 < 0 && area2 > -1e-12) area2 = 0; /* guard */
        double area = sqrt(area2);

        double r = area / s;

        double d = sqrt(r * r + (s - a) * (s - a));
        double e = sqrt(r * r + (s - b) * (s - b));
        double f = sqrt(r * r + (s - c) * (s - c));

        double r1 = r * (s - r + d - e - f) / (2.0 * (s - a));
        double r2 = r * (s - r - d + e - f) / (2.0 * (s - b));
        double r3 = r * (s - r - d - e + f) / (2.0 * (s - c));

        printf("%.6f %.6f %.6f\n", r1, r2, r3);
    }

    return 0;
}

