int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    const double PI = acos(-1.0);

    auto dist = [](double x1, double y1, double x2, double y2) {
        double dx = x1 - x2, dy = y1 - y2;
        return sqrt(dx * dx + dy * dy);
    };

    int T;
    cin >> T;
    cout.setf(ios::fixed);
    cout << setprecision(10);

    while (T--) {
        double x1, y1, x2, y2, x3, y3;
        cin >> x1 >> y1 >> x2 >> y2 >> x3 >> y3;

        // Standard notation:
        // a = |BC| opposite A
        // b = |CA| opposite B
        // c = |AB| opposite C
        double a = dist(x2, y2, x3, y3);
        double b = dist(x3, y3, x1, y1);
        double c = dist(x1, y1, x2, y2);

        double s = (a + b + c) / 2.0;

        // Area by shoelace
        double area = fabs(
            x1 * (y2 - y3) +
            x2 * (y3 - y1) +
            x3 * (y1 - y2)
        ) / 2.0;

        // Inradius
        double r = area / s;

        // Malfatti circle radii:
        // r1 tangent to sides adjacent to vertex A
        // r2 tangent to sides adjacent to vertex B
        // r3 tangent to sides adjacent to vertex C
        //
        // Closed forms:
        // r1 = r * (s - r + d - e - f) / (2*(s-a))
        // but simpler standard equivalent:
        // r1 = r/(2(s-a)) * (s - r + (s-a) - (s-b) - (s-c))
        //
        // More commonly:
        // x = sqrt(r^2 + (s-a)^2), etc.
        // r1 = (r/2) * (s-r+x-y-z)/(s-a)
        // However these simplify to the standard Malfatti formulas:
        double x = sqrt(r * r + (s - a) * (s - a));
        double y = sqrt(r * r + (s - b) * (s - b));
        double z = sqrt(r * r + (s - c) * (s - c));

        double r1 = r / (2.0 * (s - a)) * (s - r + x - y - z);
        double r2 = r / (2.0 * (s - b)) * (s - r - x + y - z);
        double r3 = r / (2.0 * (s - c)) * (s - r - x - y + z);

        cout << r1 << ' ' << r2 << ' ' << r3 << '\n';
    }

    return 0;
}

