        double c = Math.sqrt(Math.pow(x1 - x2, 2) + Math.pow(y1 - y2, 2)); // opposite C

        // Semiperimeter
        double s = (a + b + c) / 2.0;

        // Inradius
        double area = Math.abs((x1*(y2 - y3) + x2*(y3 - y1) + x3*(y1 - y2)) / 2.0);
        double r = area / s;

        // Distances from vertices to incenter
        double d1 = Math.sqrt(s * (s - a)); // distance from A to incenter? Actually not needed directly.

        // Using Malfatti radii formula:
        double r1 = r / (2.0 * (Math.tan(Math.acos((b*b + c*c - a*a)/(2*b*c)) / 4.0))); 
        // Better to compute angles first:

        double A = Math.acos((b*b + c*c - a*a) / (2*b*c));
        double B = Math.acos((a*a + c*c - b*b) / (2*a*c));
