import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        double nextDouble() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            double val = 0;
            while (c >= '0' && c <= '9') {
                val = val * 10 + (c - '0');
                c = read();
            }

            if (c == '.') {
                double mul = 0.1;
                c = read();
                while (c >= '0' && c <= '9') {
                    val += (c - '0') * mul;
                    mul *= 0.1;
                    c = read();
                }
            }

            return val * sign;
        }

        boolean hasNext() throws IOException {
            int c;
            do {
                c = read();
                if (c == -1) return false;
            } while (c <= ' ');
            ptr--;
            return true;
        }
    }

    static double dist(double x1, double y1, double x2, double y2) {
        double dx = x1 - x2, dy = y1 - y2;
        return Math.hypot(dx, dy);
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        StringBuilder out = new StringBuilder();

        while (fs.hasNext()) {
            double x1 = fs.nextDouble();
            double y1 = fs.nextDouble();
            double x2 = fs.nextDouble();
            double y2 = fs.nextDouble();
            double x3 = fs.nextDouble();
            double y3 = fs.nextDouble();

            // Side lengths:
            // a = BC, opposite A
            // b = CA, opposite B
            // c = AB, opposite C
            double a = dist(x2, y2, x3, y3);
            double b = dist(x3, y3, x1, y1);
            double c = dist(x1, y1, x2, y2);

            double s = (a + b + c) / 2.0;
            double area = Math.abs(
                    x1 * (y2 - y3) +
                    x2 * (y3 - y1) +
                    x3 * (y1 - y2)
            ) / 2.0;

            double r = area / s; // inradius

            // Standard Malfatti radii formulas
            double x = Math.sqrt(r * (s - a + r));
            double y = Math.sqrt(r * (s - b + r));
            double z = Math.sqrt(r * (s - c + r));

            double r1 = r - y - z + x; // tangent to sides around vertex A
            double r2 = r - z - x + y; // around vertex B
            double r3 = r - x - y + z; // around vertex C

            out.append(String.format(Locale.US, "%.6f %.6f %.6f%n", r1, r2, r3));
        }

        System.out.print(out.toString());
    }
